    if (s > e) {
        return ERR_SPAN_ORDER;
    }
    if ((s == NO_LINE) and (e != NO_LINE)) {
        return ERR_SPAN_ORDER;
    }
    if (e > g.line_count) {
        return ERR_SPAN_OUTSIDE;
    }
    const l: u8 = g.node_label[k];
    if ((s == NO_LINE) and ((l == LABEL_EXACT) or (l == LABEL_SUGGESTED))) {
        return ERR_SPAN_MISSING;
    }
    if ((n > 0) and (g.node_kind[k] == NODE_MODULE)) {
        return ERR_MODULE;
    }
    return GRAPH_OK;
}
pub fn with_edge(g: SpecGraph, kind: u8, f: u16, t: u16, label: u8, line: u32) SpecGraph {
    var h: SpecGraph = g;
    _ = &h;
    if (h.edge_count < MAX_EDGES) {
        const k: usize = @as(usize, @intCast(h.edge_count));
        h.edge_kind[k] = kind;
        h.edge_from[k] = f;
        h.edge_to[k] = t;
        h.edge_label[k] = label;
        h.edge_line[k] = line;
    }
    h.edge_count = h.edge_count + 1;
    return h;
}
pub fn with_node(g: SpecGraph, kind: u8, label: u8, name: []const u8, s: u32, e: u32) SpecGraph {
    var h: SpecGraph = g;
    _ = &h;
    if (h.node_count < MAX_NODES) {
        const k: usize = @as(usize, @intCast(h.node_count));
        h.node_kind[k] = kind;
        h.node_label[k] = label;
        h.node_name[k] = name;
        h.line_start[k] = s;
        h.line_end[k] = e;
    }
    h.node_count = h.node_count + 1;
    return h;
}
pub fn with_suggestion() SpecGraph {
    var g: SpecGraph = tutorial_08_graph();
    _ = &g;
    g = with_node(g, NODE_OPAQUE, LABEL_SUGGESTED, "table lookup step", 66, 72);
    g = with_edge(g, EDGE_DATA_FLOW, 6, 15, LABEL_SUGGESTED, 67);
    return g;
}
